{"content": "{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Regrow Up World - Material Data Structure",
  "description": "Proposed data structure for circular economy material lifecycle system",
  "version": "1.0.0",
  "definitions": {
    "MaterialTier": {
      "type": "string",
      "enum": ["raw", "secondary", "product", "artisan", "contaminated"],
      "description": "Material processing tier in circular economy chain"
    },
    "MaterialQuality": {
      "type": "string",
      "enum": ["A", "B", "C", "contaminated"],
      "description": "Material quality grade affecting processing yield"
    },
    "ProcessingState": {
      "type": "string",
      "enum": ["idle", "processing", "complete", "failed"],
      "description": "Current state of material in processing facility"
    }
  },
  "type": "object",
  "properties": {
    "materials": {
      "type": "object",
      "description": "Master material definitions",
      "patternProperties": {
        "^[a-z_]+$": {
          "type": "object",
          "required": ["id", "tier", "label", "icon", "description", "environmental_impact"],
          "properties": {
            "id": {
              "type": "string",
              "description": "Unique material identifier"
            },
            "tier": {
              "$ref": "#/definitions/MaterialTier"
            },
            "label": {
              "type": "string",
              "description": "Display name"
            },
            "icon": {
              "type": "string",
              "description": "Emoji or icon identifier"
            },
            "description": {
              "type": "string",
              "description": "Short description for players"
            },
            "environmental_impact": {
              "type": "object",
              "required": ["co2_saved_kg", "water_saved_liters"],
              "properties": {
                "co2_saved_kg": {
                  "type": "number",
                  "description": "kg of CO₂ saved per unit recycled",
                  "minimum": 0
                },
                "water_saved_liters": {
                  "type": "number",
                  "description": "Liters of water saved per unit recycled",
                  "minimum": 0
                },
                "energy_saved_kwh": {
                  "type": "number",
                  "description": "kWh of energy saved per unit recycled",
                  "minimum": 0
                },
                "landfill_avoided_kg": {
                  "type": "number",
                  "description": "kg of landfill waste avoided",
                  "minimum": 0
                }
              }
            },
            "economic_value": {
              "type": "object",
              "properties": {
                "sell_price_tokens": {
                  "type": "integer",
                  "description": "Regro tokens if sold directly",
                  "minimum": 0
                },
                "market_volatility": {
                  "type": "number",
                  "description": "Price fluctuation factor (0-1, higher = more volatile)",
                  "minimum": 0,
                  "maximum": 1
                }
              }
            },
            "lifecycle": {
              "type": "object",
              "properties": {
                "degradation_days": {
                  "type": "integer",
                  "description": "Days until material degrades if not processed",
                  "minimum": 1
                },
                "degradation_rate": {
                  "type": "number",
                  "description": "Percentage lost per day after degradation_days (0-1)",
                  "minimum": 0,
                  "maximum": 1
                },
                "can_be_contaminated": {
                  "type": "boolean",
                  "description": "Whether this material can become contaminated"
                },
                "contamination_chance": {
                  "type": "number",
                  "description": "Probability of contamination when collected (0-1)",
                  "minimum": 0,
                  "maximum": 1
                }
              }
            },
            "educational_content": {
              "type": "object",
              "properties": {
                "real_world_fact": {
                  "type": "string",
                  "description": "Interesting fact about this material"
                },
                "recycling_tip": {
                  "type": "string",
                  "description": "Practical recycling advice for players"
                },
                "processing_steps": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "description": "Real-world processing steps"
                },
                "common_products": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "description": "What this material is commonly made into"
                }
              }
            },
            "unlock_requirements": {
              "type": "object",
              "properties": {
                "min_level": {
                  "type": "integer",
                  "description": "Minimum player level to collect this material",
                  "minimum": 1
                },
                "required_biome": {
                  "type": "string",
                  "description": "Biome where this material appears"
                },
                "required_quest": {
                  "type": "string",
                  "description": "Quest ID that must be completed"
                }
              }
            }
          }
        }
      }
    },
    "processing_recipes": {
      "type": "object",
      "description": "Material transformation recipes",
      "patternProperties": {
        "^[a-z_]+$": {
          "type": "object",
          "required": ["id", "type", "label", "inputs", "outputs", "processing_requirements"],
          "properties": {
            "id": {
              "type": "string",
              "description": "Unique recipe identifier"
            },
            "type": {
              "type": "string",
              "enum": ["cleaning", "sulam", "cipta", "artisan"],
              "description": "Processing type"
            },
            "label": {
              "type": "string",
              "description": "Display name"
            },
            "icon": {
              "type": "string",
              "description": "Emoji or icon"
            },
            "description": {
              "type": "string",
              "description": "What this recipe does"
            },
            "inputs": {
              "type": "array",
              "items": {
                "type": "object",
                "required": ["material_id", "quantity"],
                "properties": {
                  "material_id": {
                    "type": "string"
                  },
                  "quantity": {
                    "type": "integer",
                    "minimum": 1
                  },
                  "quality_required": {
                    "$ref": "#/definitions/MaterialQuality"
                  }
                }
              },
              "minItems": 1
            },
            "outputs": {
              "type": "array",
              "items": {
                "type": "object",
                "required": ["material_id", "quantity"],
                "properties": {
                  "material_id": {
                    "type": "string"
                  },
                  "quantity": {
                    "type": "integer",
                    "minimum": 1
                  },
                  "quality": {
                    "$ref": "#/definitions/MaterialQuality"
                  },
                  "bonus_chance": {
                    "type": "number",
                    "description": "Probability of bonus output (0-1)",
                    "minimum": 0,
                    "maximum": 1
                  }
                }
              },
              "minItems": 1
            },
            "processing_requirements": {
              "type": "object",
              "properties": {
                "karsa_cost": {
                  "type": "integer",
                  "description": "KARSA energy required",
                  "minimum": 0
                },
                "processing_time_minutes": {
                  "type": "integer",
                  "description": "Real-time minutes to complete (0 = instant)",
                  "minimum": 0
                },
                "facility_level": {
                  "type": "integer",
                  "description": "Minimum facility level required",
                  "minimum": 1
                },
                "success_rate": {
                  "type": "number",
                  "description": "Base success rate (0-1, can be improved with upgrades)",
                  "minimum": 0,
                  "maximum": 1
                },
                "failure_penalty": {
                  "type": "object",
                  "properties": {
                    "inputs_lost": {
                      "type": "number",
                      "description": "Percentage of inputs lost on failure (0-1)",
                      "minimum": 0,
                      "maximum": 1
                    },
                    "karsa_refund": {
                      "type": "number",
                      "description": "Percentage of KARSA refunded on failure (0-1)",
                      "minimum": 0,
                      "maximum": 1
                    }
                  }
                }
              }
            },
            "unlock_requirements": {
              "type": "object",
              "properties": {
                "min_level": {
                  "type": "integer",
                  "minimum": 1
                },
                "required_facility_upgrades": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                },
                "required_quest": {
                  "type": "string"
                }
              }
            },
            "educational_content": {
              "type": "object",
              "properties": {
                "process_explanation": {
                  "type": "string",
                  "description": "How this process works in real life"
                },
                "environmental_benefit": {
                  "type": "string",
                  "description": "Why this process matters for circular economy"
                }
              }
            }
          }
        }
      }
    },
    "player_inventory": {
      "type": "object",
      "description": "Player's material inventory state",
      "properties": {
        "materials": {
          "type": "object",
          "patternProperties": {
            "^[a-z_]+$": {
              "type": "object",
              "required": ["material_id", "quantity", "quality", "collected_at"],
              "properties": {
                "material_id": {
                  "type": "string"
                },
                "quantity": {
                  "type": "integer",
                  "minimum": 0
                },
                "quality": {
                  "$ref": "#/definitions/MaterialQuality"
                },
                "collected_at": {
                  "type": "integer",
                  "description": "Unix timestamp when first collected"
                },
                "last_updated": {
                  "type": "integer",
                  "description": "Unix timestamp of last quantity change"
                },
                "is_contaminated": {
                  "type": "boolean",
                  "description": "Whether this batch is contaminated"
                },
                "degradation_progress": {
                  "type": "number",
                  "description": "Percentage degraded (0-1)",
                  "minimum": 0,
                  "maximum": 1
                }
              }
            }
          }
        },
        "total_collected_lifetime": {
          "type": "object",
          "description": "Lifetime collection stats for achievements",
          "patternProperties": {
            "^[a-z_]+$": {
              "type": "integer",
              "minimum": 0
            }
          }
        },
        "total_co2_saved": {
          "type": "number",
          "description": "Total kg of CO₂ saved (lifetime)",
          "minimum": 0
        },
        "total_water_saved": {
          "type": "number",
          "description": "Total liters of water saved (lifetime)",
          "minimum": 0
        }
      }
    },
    "processing_facilities": {
      "type": "object",
      "description": "Player's processing facilities state",
      "properties": {
        "cleaning_station": {
          "$ref": "#/definitions/Facility"
        },
        "sulam_refinery": {
          "$ref": "#/definitions/Facility"
        },
        "cipta_workshop": {
          "$ref": "#/definitions/Facility"
        },
        "artisan_studio": {
          "$ref": "#/definitions/Facility"
        }
      }
    },
    "processing_queue": {
      "type": "array",
      "description": "Active processing jobs",
      "items": {
        "type": "object",
        "required": ["job_id", "facility_id", "recipe_id", "state", "started_at"],
        "properties": {
          "job_id": {
            "type": "string",
            "description": "Unique job identifier"
          },
          "facility_id": {
            "type": "string",
            "description": "Which facility is processing this"
          },
          "recipe_id": {
            "type": "string",
            "description": "Recipe being executed"
          },
          "state": {
            "$ref": "#/definitions/ProcessingState"
          },
          "started_at": {
            "type": "integer",
            "description": "Unix timestamp when processing started"
          },
          "complete_at": {
            "type": "integer",
            "description": "Unix timestamp when processing will complete"
          },
          "inputs_consumed": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "material_id": {
                  "type": "string"
                },
                "quantity": {
                  "type": "integer"
                }
              }
            }
          },
          "expected_outputs": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "material_id": {
                  "type": "string"
                },
                "quantity": {
                  "type": "integer"
                }
              }
            }
          },
          "can_speed_up": {
            "type": "boolean",
            "description": "Whether player can spend tokens to instant-complete"
          },
          "speed_up_cost": {
            "type": "integer",
            "description": "Regro tokens required to instant-complete"
          }
        }
      }
    }
  },
  "definitions": {
    "Facility": {
      "type": "object",
      "required": ["level", "slots", "is_broken"],
      "properties": {
        "level": {
          "type": "integer",
          "description": "Facility upgrade level",
          "minimum": 1
        },
        "slots": {
          "type": "integer",
          "description": "Number of simultaneous processing slots",
          "minimum": 1
        },
        "is_broken": {
          "type": "boolean",
          "description": "Whether facility needs repair"
        },
        "bonuses": {
          "type": "object",
          "properties": {
            "speed_multiplier": {
              "type": "number",
              "description": "Processing speed bonus (1.0 = normal, 1.2 = 20% faster)",
              "minimum": 1.0
            },
            "yield_bonus": {
              "type": "number",
              "description": "Output quantity bonus (0.0 = none, 0.1 = 10% more)",
              "minimum": 0
            },
            "success_rate_bonus": {
              "type": "number",
              "description": "Success rate bonus (0.0 = none, 0.1 = +10%)",
              "minimum": 0
            },
            "karsa_discount": {
              "type": "number",
              "description": "KARSA cost reduction (0.0 = none, 0.2 = 20% cheaper)",
              "minimum": 0,
              "maximum": 1
            }
          }
        },
        "last_maintenance": {
          "type": "integer",
          "description": "Unix timestamp of last maintenance"
        },
        "next_breakdown_check": {
          "type": "integer",
          "description": "Unix timestamp of next breakdown probability check"
        }
      }
    }
  }
}
", "path": "/root/regrow-up-world-dev/material_schema.json"}
